	let ssample: vec3f = textureSample(texture_msdfMap, texture_msdfMapSampler, uvShdw).rgb;
	let sigDist: f32 = median(tsample.r, tsample.g, tsample.b);
	let sigDistShdw: f32 = median(ssample.r, ssample.g, ssample.b);
